(function(){
  var s=document.createElement('script');
  s.src='/feeds/posts/default/-/ব্রেকিং?alt=json-in-script&max-results=5&callback=_bkBreaking';
  document.body.appendChild(s);
})();
function _bkBreaking(d){
  if(!d.feed||!d.feed.entry)return;
  var h='';
  d.feed.entry.forEach(function(e){
    var u='#';
    for(var i=0;i<e.link.length;i++){if(e.link[i].rel==='alternate'){u=e.link[i].href;break;}}
    h+='<a href="'+u+'" style="white-space:nowrap;padding:0 20px;">'+e.title.$t+' ●</a>';
  });
  document.getElementById('breakingTicker').innerHTML=h+h;
}
