(function(){
  var s=document.createElement('script');
  s.src='/feeds/posts/default/-/এডিটর পিক?alt=json-in-script&max-results=8&callback=_bkCarousel';
  document.body.appendChild(s);
})();
function _bkCarousel(d){
  if(!d.feed||!d.feed.entry)return;
  var h='';
  d.feed.entry.forEach(function(e){
    h+='<a href="'+_gu(e)+'" class="carousel-item post-card">';
    h+='<img class="post-img" src="'+_gi(e)+'" alt="'+e.title.$t+'"/>';
    h+='<h3 class="line-clamp-2">'+e.title.$t+'</h3></a>';
  });
  document.getElementById('carouselTrack').innerHTML=h;
}
var _cPos=0;
function carouselNext(){
  var t=document.getElementById('carouselTrack');
  if(!t)return;
  var items=t.querySelectorAll('.carousel-item');
  var mx=Math.max(0,items.length-4);
  _cPos=Math.min(_cPos+1,mx);
  t.style.transform='translateX(-'+(_cPos*25)+'%)';
  t.style.transition='transform .5s';
}
function carouselPrev(){
  var t=document.getElementById('carouselTrack');
  if(!t)return;
  _cPos=Math.max(0,_cPos-1);
  t.style.transform='translateX(-'+(_cPos*25)+'%)';
  t.style.transition='transform .5s';
}
setInterval(function(){carouselNext();if(_cPos>=4)_cPos=-1;},4000);
//

