(function(){
  var s=document.createElement('script');
  s.src='/feeds/posts/default/-/মত-দ্বিমত?alt=json-in-script&max-results=4&callback=_bkOpinion';
  document.body.appendChild(s);
})();
function _bkOpinion(d){
  if(!d.feed||!d.feed.entry)return;
  var h='';
  d.feed.entry.forEach(function(e){
    var ai=(e.author&&e.author[0]&&e.author[0].gd$image&&e.author[0].gd$image.src!=='https://img1.blogblog.com/img/b16-rounded.gif')?e.author[0].gd$image.src:'https://via.placeholder.com/64';
    var an=e.author&&e.author[0]?e.author[0].name.$t:'Unknown';
    h+='<a href="'+_gu(e)+'" class="card post-card opinion-card" style="display:block;">';
    h+='<img class="author-img" src="'+ai+'" alt="'+an+'"/>';
    h+='<h4 class="author-name">'+an+'</h4>';
    h+='<h3 style="font-size:12px;line-height:1.6;color:var(--muted-fg);margin-top:8px;"><span class="quote-mark">'+e.title.$t+'</span></h3>';
    h+='</a>';
  });
  document.getElementById('opinionSection').innerHTML=h;
}
