body.script:
//

// ===== Mobile Menu =====
function toggleMobileMenu() {
  var overlay = document.getElementById('mobileOverlay');
  var drawer = document.getElementById('mobileDrawer');
  overlay.classList.toggle('open');
  drawer.classList.toggle('open');
  document.body.style.overflow = drawer.classList.contains('open') ? 'hidden' : '';
}

// ===== Sticky Nav =====
window.addEventListener('scroll', function() {
  var stickyNav = document.getElementById('stickyNav');
  if (window.scrollY > 150) {
    stickyNav.classList.add('visible');
  } else {
    stickyNav.classList.remove('visible');
  }
});

// ===== Tab Switching =====
function switchTab(btn, tabId) {
  var parent = btn.closest('.sidebar-tabs');
  var btns = parent.querySelectorAll('.tab-btn');
  var contents = parent.querySelectorAll('.tab-content');
  btns.forEach(function(b) { b.classList.remove('active'); });
  contents.forEach(function(c) { c.style.display = 'none'; });
  btn.classList.add('active');
  document.getElementById(tabId).style.display = 'block';
}

// ===== Helper Functions =====
function _gi(entry) {
  if (entry.media$thumbnail) return entry.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/s600/');
  var content = entry.content ? entry.content.$t : '';
  var match = content.match(/<img[^>]+src=["']([^"']+)["']/);
  return match ? match[1] : 'https://via.placeholder.com/600x400?text=No+Image';
}

function _gu(entry) {
  for (var i = 0; i < entry.link.length; i++) {
    if (entry.link[i].rel === 'alternate') return entry.link[i].href;
  }
  return '#';
}

function _ge(entry, len) {
  var text = entry.summary ? entry.summary.$t : (entry.content ? entry.content.$t.replace(/<[^>]+>/g, '') : '');
  return text.substring(0, len || 100) + '...';
}

// ===== Render: Highlight =====
function _renderHighlight(containerId, d) {
  if (!d.feed || !d.feed.entry) return;
  var entries = d.feed.entry;
  var h = '<div class="highlight-grid">';
  var e = entries[0];
  h += '<a href="' + _gu(e) + '" class="card post-card" style="display:block;">';
  h += '<div class="overflow-hidden aspect-video"><img class="post-img" src="' + _gi(e) + '" alt="' + e.title.$t + '" style="width:100%;height:100%;object-fit:cover;"/></div>';
  h += '<div style="padding:16px;"><h3 style="font-size:16px;font-weight:700;line-height:1.6;">' + e.title.$t + '</h3>';
  h += '<p style="font-size:13px;color:var(--muted-fg);margin-top:4px;" class="line-clamp-2">' + _ge(e, 100) + '</p></div></a>';
  h += '<div class="highlight-side">';
  for (var i = 1; i < entries.length; i++) {
    var s = entries[i];
    h += '<a href="' + _gu(s) + '" class="side-item post-card">';
    h += '<img src="' + _gi(s) + '" alt="' + s.title.$t + '"/>';
    h += '<h4 class="line-clamp-3">' + s.title.$t + '</h4></a>';
  }
  h += '</div></div>';
  document.getElementById(containerId).innerHTML = h;
}

