    h += '<div class="overflow-hidden ' + (aspectClass || 'aspect-video') + '"><img class="post-img" src="' + _gi(e) + '" alt="' + e.title.$t + '" style="width:100%;height:100%;object-fit:cover;"/></div>';
    h += '<div style="padding:8px;"><h3 style="font-size:12px;font-weight:700;line-height:1.6;" class="line-clamp-2">' + e.title.$t + '</h3></div></a>';
