// ===== Render: National (hero + side + bottom grid) =====
function _renderNational(containerId, d) {
  if (!d.feed || !d.feed.entry) return;
  var e = d.feed.entry;
  var h = '<div class="national-grid">';
  // Hero
  h += '<a href="' + _gu(e[0]) + '" class="national-hero post-card">';
  h += '<img src="' + _gi(e[0]) + '" alt="' + e[0].title.$t + '"/>';
  h += '<div class="overlay"></div>';
  h += '<div class="caption"><span>জাতীয়</span><h3 class="line-clamp-3">' + e[0].title.$t + '</h3></div></a>';
  // Right side
  h += '<div style="display:flex;flex-direction:column;gap:8px;">';
  if (e[1]) {
    h += '<a href="' + _gu(e[1]) + '" class="national-side-card post-card">';
    h += '<img src="' + _gi(e[1]) + '" alt="' + e[1].title.$t + '"/>';
    h += '<div class="overlay"></div><h4 class="line-clamp-2">' + e[1].title.$t + '</h4></a>';
  }
  for (var i = 2; i < Math.min(5, e.length); i++) {
    h += '<a href="' + _gu(e[i]) + '" class="national-side-list post-card">';
    h += '<img src="' + _gi(e[i]) + '" alt="' + e[i].title.$t + '"/>';
    h += '<h4 class="line-clamp-2">' + e[i].title.$t + '</h4></a>';
  }
  h += '</div></div>';
  // Bottom row
  if (e.length > 4) {
    h += '<div class="national-bottom">';
    for (var j = 4; j < Math.min(8, e.length); j++) {
      h += '<a href="' + _gu(e[j]) + '" class="national-bottom-card post-card">';
      h += '<img src="' + _gi(e[j]) + '" alt="' + e[j].title.$t + '"/>';
