// ===== Render: FotoCard =====
function _renderFotoCard(containerId, d) {
  if (!d.feed || !d.feed.entry) return;
  var today = new Date();
  var bn = ['০','১','২','৩','৪','৫','৬','৭','৮','৯'];
  var months = ['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'];
  var dayStr = String(today.getDate()).split('').map(function(c){return bn[c]||c;}).join('');
  var yearStr = String(today.getFullYear()).split('').map(function(c){return bn[c]||c;}).join('');
  var dateStr = dayStr + ' ' + months[today.getMonth()] + ' ' + yearStr;
  var h = '';
  d.feed.entry.forEach(function(e) {
    var ai = (e.author && e.author[0] && e.author[0].gd$image && e.author[0].gd$image.src !== 'https://img1.blogblog.com/img/b16-rounded.gif') ? e.author[0].gd$image.src : 'https://via.placeholder.com/64';
    var an = e.author && e.author[0] ? e.author[0].name.$t : 'Unknown';
    h += '<a href="' + _gu(e) + '" class="fotocard-item">';
    h += '<div class="fc-top"><span class="fc-date">' + dateStr + '</span><span class="fc-quote-icon">❝</span></div>';
    h += '<div class="fc-text line-clamp-5">' + _ge(e, 200) + '</div>';
    h += '<div class="fc-author"><img src="' + ai + '" alt="' + an + '"/><div><h4>' + an + '</h4><p>কলামিস্ট</p></div></div>';
    h += '<div class="fc-brand"><span>বেলাভূমি কণ্ঠ</span><small>belabhuminews.com</small></div></a>';
  });
  document.getElementById(containerId).innerHTML = h;
}

