// ===== Related Posts (Post Page) =====
(function() {
  var labels = document.querySelectorAll('.post-label-tag');
  if (labels.length > 0) {
    var lbl = labels[0].textContent.trim();
    var s = document.createElement('script');
    s.src = '/feeds/posts/default/-/' + encodeURIComponent(lbl) + '?alt=json-in-script&max-results=4&callback=_bkRelated';
    document.body.appendChild(s);
  }
})();
function _bkRelated(d) {
  if (!d.feed || !d.feed.entry) return;
  var h = '';
  d.feed.entry.slice(0, 4).forEach(function(e) {
    h += '<a href="' + _gu(e) + '" class="related-item post-card">';
    h += '<img src="' + _gi(e) + '" alt="' + e.title.$t + '"/>';
    h += '<div><h4 class="line-clamp-3">' + e.title.$t + '</h4></div></a>';
  });
  var el = document.getElementById('relatedPosts');
  if (el) el.innerHTML = h;
}

